#undef QSB_JUMP_STORAGE

template<int SHIFT> ZI_DEV int32_t qsb_jump_coefficient(uint64_t packed){
    const uint32_t word=(uint32_t)(packed>>SHIFT);
#ifdef __CUDA_ARCH__
    int32_t out;
    asm("bfe.s32 %0,%1,0,12;" : "=r"(out) : "r"(word));
    return out;
#else
    return (int32_t)((word&4095u)^2048u)-2048;
#endif
}
ZI_DEV int32_t qsb_divstep30_odd(int32_t delta,uint32_t f,uint32_t g,
                                   int32_t *ra,int32_t *rb,int32_t *rc,int32_t *rd){
    // Requires odd delta. Root starts at one; each 30-step batch preserves parity.
    int32_t u=1,v=0,q=0,r=1;
    #pragma unroll
    for(int step=0;step<3;step++){
        const int32_t dc=delta<-9?-9:(delta>9?9:delta);
        uint32_t fi=(3u*f)^2u;           // inverse mod32 for every odd f
        fi*=2u-f*fi;                     // exactly the required inverse mod1024
        const uint32_t ratio=(g*fi)&1023u;
        const uint32_t index=((uint32_t)(dc+9)>>1)*1024u+ratio;
#ifdef __CUDA_ARCH__
        const uint64_t packed=(uint64_t)__ldg(&QSB_JUMP10[index]);
#else
        const uint64_t packed=(uint64_t)QSB_JUMP10[index];
#endif
        const int32_t a=qsb_jump_coefficient<0>(packed),b=qsb_jump_coefficient<12>(packed);
        const int32_t c=qsb_jump_coefficient<24>(packed),d=qsb_jump_coefficient<36>(packed);
        const uint32_t nf=((uint32_t)a*f+(uint32_t)b*g)>>10;
        g=((uint32_t)c*f+(uint32_t)d*g)>>10;f=nf;
        const int32_t nu=a*u+b*q,nv=a*v+b*r;
        q=c*u+d*q;r=c*v+d*r;u=nu;v=nv;
        const uint32_t flags=(uint32_t)(packed>>32);
        const int32_t sm=(int32_t)flags>>31;
        delta=((delta^sm)-sm)+zi_by_signed_byte<2>(flags);
    }
    *ra=u;*rb=v;*rc=q;*rd=r;return delta;
}
// Each deciding lane owns one column; both follow identical f/g/delta.
ZI_DEV int32_t qsb_divstep30_column(int32_t delta,uint32_t f,uint32_t g,
                                   bool column,int32_t *ru,int32_t *rq){
    // Requires odd delta. Root starts at one; each 30-step batch preserves parity.
    int32_t u=0,q=0;
    #pragma unroll
    for(int step=0;step<3;step++){
        const int32_t dc=delta<-9?-9:(delta>9?9:delta);
        uint32_t fi=(3u*f)^2u;           // inverse mod32 for every odd f
        fi*=2u-f*fi;                     // exactly the required inverse mod1024
        const uint32_t ratio=(g*fi)&1023u;
        const uint32_t index=((uint32_t)(dc+9)>>1)*1024u+ratio;
#ifdef __CUDA_ARCH__
        const uint64_t packed=(uint64_t)__ldg(&QSB_JUMP10[index]);
#else
        const uint64_t packed=(uint64_t)QSB_JUMP10[index];
#endif
        const int32_t a=qsb_jump_coefficient<0>(packed),b=qsb_jump_coefficient<12>(packed);
        const int32_t c=qsb_jump_coefficient<24>(packed),d=qsb_jump_coefficient<36>(packed);
        const uint32_t nf=((uint32_t)a*f+(uint32_t)b*g)>>10;
        g=((uint32_t)c*f+(uint32_t)d*g)>>10;f=nf;
        if(step==0){u=column?b:a;q=column?d:c;}
        else{const int32_t nu=a*u+b*q;q=c*u+d*q;u=nu;}
        const uint32_t flags=(uint32_t)(packed>>32);
        const int32_t sm=(int32_t)flags>>31;
        delta=((delta^sm)-sm)+zi_by_signed_byte<2>(flags);
    }
    *ru=u;*rq=q;return delta;
}
// General entry is retained for independent auditing and future callers.
ZI_DEV int32_t qsb_divstep30_direct(int32_t delta,uint32_t f,uint32_t g,
                                  int32_t *a,int32_t *b,int32_t *c,int32_t *d){
    return (delta&1)?qsb_divstep30_odd(delta,f,g,a,b,c,d):
                     zi_divstep30_by(delta,f,g,a,b,c,d);
}
